const NODE_W = 260;
// Match `.node-card--theme { min-height: 200px }`. Earlier #79 used
// 216 to leave a buffer for tall cards that would otherwise clip
// inside the foreignObject viewport, but #93 enabled
// `foreignObject overflow="visible"` so cards can grow beyond the
// declared height without clipping. The 16 px buffer was visible as
// a "frame mismatch" — edges connected at the bottom of the
// foreignObject (216) instead of the visible card bottom (200),
// leaving 16 px of empty space between the card border and the
// edge endpoint. Aligning NODE_H to the actual card height makes
// edges land exactly on the card's bottom edge.
const NODE_H = 200;
const ROW_GAP = 80;        // vertical gap between year rows
const SIBLING_GAP = 28;    // horizontal gap between within-year siblings
const PADDING = 56;
const YEAR_LABEL_W = 84;   // left gutter reserved for year axis labels

const SVG_NS = "http://www.w3.org/2000/svg";
const XHTML_NS = "http://www.w3.org/1999/xhtml";

const STORAGE_KEY = "pp.theme.prefs";

const UNKNOWN_YEAR = "__unknown__";

// Plausible year window for academic publications. Anything outside this
// range is treated as bad data and pushed to the Unknown bucket so it
// can't visually collide with legitimate entries (e.g. a corrupted
// year=0 / year=-1 / year=99999 wouldn't show up at the top of the
// chronological axis next to real 1980-era papers). The lower bound is
// generous (1900) so historical-reference cards (PRML, classic stats
// textbooks) still render in the right row; the upper bound floats with
// the calendar year so the viewer keeps working without source edits as
// time passes.
const MIN_PLAUSIBLE_YEAR = 1900;
const MAX_PLAUSIBLE_YEAR = new Date().getFullYear() + 2;

// Detect "year vs venue mismatch" — the venue string usually carries the
// publication year (e.g. "NeurIPS 2022", "ICLR 2014"). When the year
// field disagrees with the year embedded in the venue, the data has
// been corrupted somewhere upstream (build_theme_lineage.py bug, partial
// JSON merge, stale cache, etc.). We don't auto-correct (the venue
// year could itself be wrong) but we surface a one-time warning so the
// anomaly is visible to anyone with devtools open. Pure side effect;
// layout proceeds with whatever year is in the data.
const _venueWarnedFor = new Set();
function checkVenueYearConsistency(node) {
  if (!node || _venueWarnedFor.has(node.id)) return;
  const v = typeof node.venue === "string" ? node.venue : "";
  const m = v.match(/\b(19[5-9]\d|20\d{2})\b/);
  if (!m) return;
  const venueYear = parseInt(m[1], 10);
  if (typeof node.year === "number" && Number.isInteger(node.year)
      && Math.abs(venueYear - node.year) >= 2) {
    _venueWarnedFor.add(node.id);
    console.warn(
      `[layout] node ${node.id}: year=${node.year} disagrees with venue ${JSON.stringify(v)} `
      + `(venue suggests ${venueYear}). Layout will use year=${node.year}; check the source data.`
    );
  }
}

// Bucket key for a node's year. Returns the year (Number) when it's a
// finite integer in the plausible range, otherwise the UNKNOWN_YEAR
// sentinel. Surfaces a one-time console.warn for anomalies so silent
// data corruption is observable to anyone with devtools open.
const _yearWarnedFor = new Set();
function bucketYear(year, nodeId) {
  if (typeof year !== "number" || !Number.isFinite(year) || !Number.isInteger(year)) {
    if (nodeId && !_yearWarnedFor.has(nodeId)) {
      _yearWarnedFor.add(nodeId);
      console.warn(`[layout] node ${nodeId}: year=${JSON.stringify(year)} is not an integer; bucketed as Unknown`);
    }
    return UNKNOWN_YEAR;
  }
  if (year < MIN_PLAUSIBLE_YEAR || year > MAX_PLAUSIBLE_YEAR) {
    if (nodeId && !_yearWarnedFor.has(nodeId)) {
      _yearWarnedFor.add(nodeId);
      console.warn(`[layout] node ${nodeId}: year=${year} is out of plausible range [${MIN_PLAUSIBLE_YEAR}, ${MAX_PLAUSIBLE_YEAR}]; bucketed as Unknown`);
    }
    return UNKNOWN_YEAR;
  }
  return year;
}

function loadPrefs() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}
function savePrefs() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      visibleRelations: [...state.visibleRelations],
      xAxisMode: state.xAxisMode,
    }));
  } catch { /* localStorage disabled */ }
}

const prefs = loadPrefs();
const state = {
  data: null,
  manifest: [],
  currentSlug: null,
  visibleRelations: new Set(
    Array.isArray(prefs?.visibleRelations) && prefs.visibleRelations.length > 0
      ? prefs.visibleRelations.filter((r) => ALL_RELATIONS.includes(r))
      : DEFAULT_RELATIONS,
  ),
  // #61: search query (lowercased). Empty string = no filter applied.
  searchQuery: "",
  // #62: year-range filter. null/null = no filter applied.
  yearRange: { min: null, max: null },
  // X-axis encoding mode. Validated against allowlist before use because
  // localStorage is user-controlled and bad values would silently corrupt
  // layout.
  xAxisMode: typeof prefs?.xAxisMode === "string" && X_AXIS_MODES.includes(prefs.xAxisMode)
    ? prefs.xAxisMode
    : DEFAULT_X_AXIS_MODE,
  // Hide orphan papers (no incident edge). Default off — orphans are
  // topically relevant to the theme even when LLM dropped their edges
  // as `unrelated`. URL: ?orphan=hide.
  hideOrphans: false,
  orphanSet: new Set(),
};

// #61: matchesSearch — case-insensitive needle in title / authors / venue.
// Returns true when the query is empty so an empty box keeps everything
// visible. Pulled out so render() and tests can share the same predicate.
function matchesSearch(node, q) {
  if (!q) return true;
  const needle = q.toLowerCase();
  if ((node.title || "").toLowerCase().includes(needle)) return true;
  if ((node.venue || "").toLowerCase().includes(needle)) return true;
  for (const a of node.authors || []) {
    if (typeof a === "string" && a.toLowerCase().includes(needle)) return true;
  }
  return false;
}

// #62: matchesYear — true when node.year is within [min, max] inclusive.
// Null bounds (no filter) and unknown years (year not numeric) both pass.
function matchesYear(node, min, max) {
  if (min == null && max == null) return true;
  const y = node.year;
  if (typeof y !== "number") return true; // unknown-year nodes always shown
  if (min != null && y < min) return false;
  if (max != null && y > max) return false;
  return true;
}

